test('localLink handles subscriptions with async iterables, observables, and tracked envelopes', async () => {
  const ee = new EventEmitter();
  const t = initTRPC.create();

  const router = t.router({
    trackedSub: t.procedure.subscription(async function* (opts) {
      let id = 0;
      for await (const [msg] of on(ee, 'tracked', {
        signal: opts.signal,
      })) {
        id++;
        yield tracked(String(id), String(msg));
      }
    }),
    obsSub: t.procedure.subscription(() => {
      return observable<string>((emit) => {
        const listener = (msg: string) => emit.next(msg);
        ee.on('obs', listener);
        return () => {
          ee.off('obs', listener);
        };
      });
    }),
  });

  const client = createTRPCClient<typeof router>({
    links: [localLink({ router })],
  });

  const trackedItems: Array<{ id: string; data: string }> = [];
  const trackedSub = client.trackedSub.subscribe(undefined, {
    onData(data) {
      trackedItems.push(data);
    },
  });

  await vi.waitFor(() => {
    expect(ee.listenerCount('tracked')).toBe(1);
  });

  ee.emit('tracked', 'a');
  await vi.waitFor(() => {
    expect(trackedItems).toEqual([{ id: '1', data: 'a' }]);
  });

  trackedSub.unsubscribe();
  await vi.waitFor(() => {
    expect(ee.listenerCount('tracked')).toBe(0);
  });

  const obsItems: string[] = [];
  const obsSub = client.obsSub.subscribe(undefined, {
    onData(data) {
      obsItems.push(data);
    },
  });

  await vi.waitFor(() => {
    expect(ee.listenerCount('obs')).toBe(1);
  });

  ee.emit('obs', 'hello-obs');
  await vi.waitFor(() => {
    expect(obsItems).toEqual(['hello-obs']);
  });

  obsSub.unsubscribe();
  await vi.waitFor(() => {
    expect(ee.listenerCount('obs')).toBe(0);
  });
});
